// Future act maps, generated by the game's own StandardActMap via tools/rng-harness
// (`map` mode). Needs the .NET SDK and the game installed; built once, cached per seed/act.
const { execFile } = require('child_process');
const fs = require('fs');
const path = require('path');

const HARNESS = path.join(__dirname, '..', 'tools', 'rng-harness');
const OUT = path.join(HARNESS, 'out');
const DLL = path.join(OUT, 'Harness.dll');

let building = null;
const cache = new Map();

function run(cmd, args, opts = {}) {
  return new Promise((resolve, reject) => {
    execFile(cmd, args, { maxBuffer: 16 * 1024 * 1024, timeout: 300000, ...opts }, (err, stdout, stderr) => {
      if (err) reject(new Error(`${cmd} ${args[0]} failed: ${stderr || err.message}`));
      else resolve(stdout);
    });
  });
}

function ensureBuilt() {
  if (fs.existsSync(DLL)) return Promise.resolve();
  if (!building) {
    building = run('dotnet', ['build', HARNESS, '-c', 'Release', '-o', OUT,
      `-p:BaseIntermediateOutputPath=${path.join(OUT, 'obj')}${path.sep}`])
      .finally(() => { building = null; });
  }
  return building;
}

// Map for act `actIndex` in current_run.save's saved_map shape.
async function generateActMap(save, actIndex) {
  const act = save.acts[actIndex];
  const key = `${save.rng.seed}|${actIndex}|${act.id}|${save.ascension}`;
  if (!cache.has(key)) {
    const job = (async () => {
      await ensureBuilt();
      const out = await run('dotnet', [DLL, 'map', save.rng.seed, String(actIndex), act.id,
        String(save.ascension ?? 0), String(save.players.length), act.rooms?.second_boss_id ? '1' : '0']);
      // The game's logger may print a line before the JSON.
      return JSON.parse(out.slice(out.indexOf('{')));
    })();
    cache.set(key, job);
    job.catch(() => cache.delete(key));
  }
  return cache.get(key);
}

module.exports = { generateActMap };
